 for(const topic of schoolTopics){
  if(topic.track!=='base'||topic.spec!==null||topic.minutes<10||topic.minutes>15)errors.push(`Invalid school topic metadata ${topic.id}`);
  if(topic.prerequisites.some(id=>!knownPrerequisites.has(id)))errors.push(`Invalid prerequisite ${topic.id}`);
  if(topic.tasks.length<15||[1,2,3].some(l=>topic.tasks.filter(t=>t.level===l).length<5))errors.push(`Insufficient task levels ${topic.id}`);
  const lesson=topic.lesson;
  if(![topic.title,topic.description,lesson.goal,lesson.explanation,lesson.simpler,lesson.formula,lesson.terms,lesson.checkpoint.question,lesson.checkpoint.answer,lesson.checkpoint.why].every(bilingual)||lesson.blocks.length<3||lesson.blocks.some(block=>!bilingual(block.title)||!bilingual(block.body)))errors.push(`Incomplete bilingual lesson ${topic.id}`);
  if(lesson.examples.length<3||[...lesson.examples,lesson.guided].some(example=>!bilingual(example.problem)||!example.answer||example.steps.ru.length<2||example.steps.kk.length<2))errors.push(`Incomplete worked examples ${topic.id}`);
  if(!lesson.examples.every((ex,i)=>JSON.stringify(ex.problem)===JSON.stringify(topic.tasks[[0,5,10][i]].prompt))||JSON.stringify(lesson.guided.problem)!==JSON.stringify(topic.tasks[1].prompt)||JSON.stringify(lesson.checkpoint.question)!==JSON.stringify(topic.tasks[2].prompt))errors.push(`Model task indices differ ${topic.id}`);
  for(const task of topic.tasks){
   if(ids.has(task.id))errors.push(`Duplicate task ${task.id}`);ids.add(task.id);
   if(!bilingual(task.prompt)||!bilingual(task.commonError)||task.solution.ru.length<2||task.solution.kk.length<2||task.hints.ru.length<3||task.hints.kk.length<3)errors.push(`Incomplete task ${task.id}`);
   const validAnswer=task.type==='multiple'?Array.isArray(task.answer)&&task.answer.length>0&&new Set(task.answer).size===task.answer.length&&task.answer.every(answer=>typeof answer==='string'&&(task.options??[]).includes(answer)):typeof task.answer==='string'&&task.answer.trim().length>0&&(task.type!=='number'||Number.isFinite(Number(task.answer)));
   if(!validAnswer)errors.push(`Invalid school answer shape ${task.id}`);
   const condition=JSON.stringify({prompt:task.prompt,type:task.type,options:task.options,unit:task.unit,tolerance:task.tolerance});
   if(conditions.get(task.id)!==condition)errors.push(`Published condition changed ${task.id}`);
   const index=Number(task.id.split('-').at(-1))-1,n=index%5+1;
   if(!Number.isInteger(index)||index<0||index>14||task.topicId!==topic.id||task.level!==Math.floor(index/5)+1||!mathCheck(task,n))errors.push(`Independent school math check ${task.id}`);
   mathematicalChecks++;
  }
 }
